export function App() {
  const hasSet = useReader((s) => s.set !== null)
  return hasSet ? <Shell /> : <div className="shell"><Dropzone /></div>
}

export class ExportTooLargeError extends Error {
  constructor(bytes: number) {
    super(
      `This export is ${(bytes / 1024 / 1024).toFixed(1)} MB, over the ` +
        `${LIMITS.pdfBodyLimitBytes / 1024 / 1024} MB limit. Try the ` +
        'self-contained HTML export instead.',
    )
    this.name = 'ExportTooLargeError'
  }
}

export interface PdfOptions {
  readonly html: string
  readonly title: string
  readonly format?: 'A4' | 'Letter'
}

export async function requestPdf({ html, title, format = 'A4' }: PdfOptions): Promise<Blob> {
  // Checked here as well as on the server: a clear message beats a 413.
  const bytes = new Blob([html]).size
  if (bytes > LIMITS.pdfBodyLimitBytes) throw new ExportTooLargeError(bytes)

  const response = await fetch('/api/export/pdf', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ html, title, format }),
  })

  if (!response.ok) {
    const message = await response
      .json()
      .then((body: unknown) =>
        typeof body === 'object' && body !== null && 'error' in body
          ? String((body as { error: unknown }).error)
          : null,
      )
      .catch(() => null)

    throw new Error(
      message ??
        (response.status === 413
          ? 'This export is too large for the print service.'
          : `The print service returned ${response.status}.`),
    )
  }

  return response.blob()
}

export function downloadBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = filename
  link.rel = 'noopener'
  document.body.append(link)
  link.click()
  link.remove()
  setTimeout(() => URL.revokeObjectURL(url), 10_000)
}

async function toDataUri(url: string): Promise<string | null> {
  try {
    const response = await fetch(url)
    if (!response.ok) return null
    const blob = await response.blob()
    return await new Promise<string | null>((resolve) => {
      const reader = new FileReader()
      reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : null)
      reader.onerror = () => resolve(null)
      reader.readAsDataURL(blob)
    })
  } catch {
    return null
  }
}

async function collectCss(): Promise<string> {
  const parts: string[] = []

  for (const sheet of Array.from(document.styleSheets)) {
    let text = ''
    try {
      text = Array.from(sheet.cssRules)
        .map((rule) => rule.cssText)
        .join('\n')
    } catch {
      // A cross-origin sheet cannot be read. There should be none - the app
      // makes no third-party requests - so this is a safety net, not a path.
      continue
    }

    // Resolve relative url() references against the sheet, then inline them.
    const base = sheet.href ?? document.baseURI
    const urls = new Set(
      [...text.matchAll(/url\((['"]?)([^'")]+)\1\)/g)]
        .map((m) => m[2])
        .filter((u): u is string => u !== undefined && !u.startsWith('data:')),
    )

    for (const url of urls) {
      const absolute = new URL(url, base).href
      const dataUri = await toDataUri(absolute)
      if (dataUri !== null) text = text.split(url).join(dataUri)
    }

    parts.push(text)
  }

  return parts.join('\n')
}

async function inlineImages(root: HTMLElement): Promise<void> {
  const images = [...root.querySelectorAll('img')]
  await Promise.all(
    images.map(async (img) => {
      const src = img.getAttribute('src')
      if (src === null || src.startsWith('data:')) return
      const dataUri = await toDataUri(src)
      if (dataUri !== null) img.setAttribute('src', dataUri)
      else img.removeAttribute('src')
      // Lazy loading is meaningless in a static file and blocks printing.
      img.removeAttribute('loading')
      img.removeAttribute('decoding')
    }),
  )
}

export interface StandaloneOptions {
  readonly set: DocumentSet
  /** Rendered results, in reading order. */
  readonly results: readonly RenderResult[]
}

export async function buildStandalone({ set, results }: StandaloneOptions): Promise<string> {
  const byId = new Map(results.map((r) => [r.docId, r]))

  // A detached host, so building the export never disturbs what is on screen.
  const host = document.createElement('div')
  host.className = 'export-root'

  for (const doc of set.docs) {
    const result = byId.get(doc.id)
    if (!result || doc.error !== null) continue

    const article = document.createElement('article')
    article.className = 'doc'

    const header = document.createElement('header')
    header.className = 'doc-head'
    const title = document.createElement('h1')
    title.className = 'doc-title'
    title.id = `doc-${doc.id}`
    title.textContent = doc.title
    header.append(title)

    const body = document.createElement('div')
    body.className = 'prose'
    // Pipeline output, already past the trust boundary.
    body.innerHTML = result.html

    article.append(header, body)
    host.append(article)
  }

  // Diagrams must be static SVG before serialising: the print context runs
  // with JavaScript disabled, so a placeholder left here never becomes a
  // diagram. Anything already drawn on screen is copied; the rest - every
  // document the reader never opened - is drawn here.
  await whenDiagramsSettled()
  copyRenderedDiagrams(host)

  // mermaid measures text, so the host must be laid out. Attached off-screen
  // rather than detached, then removed once the SVG is in hand.
  host.style.position = 'fixed'
  host.style.left = '-10000px'
  host.style.top = '0'
  host.style.width = '820px'
  document.body.append(host)
  try {
    await drawDiagramsIn(host, allMermaidBlocks(results))
  } finally {
    host.remove()
    host.removeAttribute('style')
  }

  await inlineImages(host)
  const css = await collectCss()

  return [
    '<!doctype html>',
    '<html lang="en">',
    '<head>',
    '<meta charset="utf-8">',
    '<meta name="viewport" content="width=device-width, initial-scale=1">',
    `<title>${escapeHtml(set.rootName)}</title>`,
    `<style>\n${css}\n</style>`,
    '</head>',
    '<body>',
    host.outerHTML,
    '</body>',
    '</html>',
  ].join('\n')
}

function allMermaidBlocks(results: readonly RenderResult[]) {
  return results.flatMap((r) => [...r.mermaidBlocks])
}

function copyRenderedDiagrams(host: HTMLElement): void {
  for (const figure of host.querySelectorAll<HTMLElement>('[data-mermaid]')) {
    const id = figure.getAttribute('data-mermaid')
    if (id === null) continue

    const drawn = document.querySelector(`[data-mermaid="${CSS.escape(id)}"] .mermaid-slot svg`)
    const slot = figure.querySelector<HTMLElement>('.mermaid-slot')
    if (!drawn || !slot) continue

    slot.replaceChildren(drawn.cloneNode(true))
    slot.classList.add('is-drawn')
  }
}

export function downloadStandalone(html: string, filename: string): void {
  const blob = new Blob([html], { type: 'text/html;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = filename
  link.rel = 'noopener'
  document.body.append(link)
  link.click()
  link.remove()
  // Revoking immediately can cancel the download in some browsers.
  setTimeout(() => URL.revokeObjectURL(url), 10_000)
}

export const safeFilename = (name: string, extension: string): string => {
  const base = name.replace(/[^\w.-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80)
  return `${base === '' ? 'documents' : base}.${extension}`
}

export function resolveRelative(fromDocPath: string, target: string): string {
  if (/^[a-z][a-z0-9+.-]*:/i.test(target)) return target // absolute URL scheme
  if (target.startsWith('/')) return normaliseAssetPath(target)

  const slash = fromDocPath.lastIndexOf('/')
  const baseDir = slash === -1 ? '' : fromDocPath.slice(0, slash)

  const segments = baseDir === '' ? [] : baseDir.split('/')
  for (const part of target.replace(/\\/g, '/').split('/')) {
    if (part === '' || part === '.') continue
    if (part === '..') segments.pop()
    else segments.push(part)
  }
  return normaliseAssetPath(segments.join('/'))
}

export function extensionOf(path: string): string {
  const dot = path.lastIndexOf('.')
  return dot === -1 ? '' : path.slice(dot).toLowerCase()
}

export function mimeFor(path: string, fallback: string): string {
  return MIME_BY_EXT[extensionOf(path)] ?? (fallback !== '' ? fallback : 'application/octet-stream')
}

export function buildAssetMap(
  files: readonly { path: string; file: File }[],
): Map<string, AssetRef> {
  const map = new Map<string, AssetRef>()

  for (const { path, file } of files) {
    if (!isImagePath(path)) continue
    const key = normaliseAssetPath(path)
    if (map.has(key)) continue // first wins; a duplicate key is a collision, not an update

    // The blob is retyped from the file extension rather than trusting
    // `file.type`. A File produced by a directory drop often carries an empty
    // type, and an untyped blob becomes `data:text/plain` when the exporter
    // reads it back - which no browser will render as an image.
    const mime = mimeFor(path, file.type)
    const typed = file.type === mime ? file : new Blob([file], { type: mime })

    map.set(key, {
      path: key,
      originalPath: path,
      url: URL.createObjectURL(typed),
      mime,
      bytes: file.size,
    })
  }

  return map
}

export function lookupAsset(
  assets: ReadonlyMap<string, AssetRef>,
  fromDocPath: string,
  target: string,
): AssetRef | null {
  const resolved = resolveRelative(fromDocPath, target)
  const direct = assets.get(resolved)
  if (direct) return direct

  const bare = resolved.slice(resolved.lastIndexOf('/') + 1)
  if (bare === '') return null

  let match: AssetRef | null = null
  for (const asset of assets.values()) {
    if (asset.path.endsWith(`/${bare}`) || asset.path === bare) {
      // Ambiguous basename: refuse rather than guess at the wrong image.
      if (match) return null
      match = asset
    }
  }
  return match
}

export function revokeAssets(assets: ReadonlyMap<string, AssetRef>): void {
  for (const asset of assets.values()) URL.revokeObjectURL(asset.url)
}

export function hashPath(path: string): string {
  let hash = 0x811c9dc5
  for (let i = 0; i < path.length; i++) {
    hash ^= path.charCodeAt(i)
    hash = Math.imul(hash, 0x01000193) >>> 0
  }
  return hash.toString(36).padStart(7, '0')
}

export interface Frontmatter {
  readonly data: Record<string, unknown>
  /** The document body with the frontmatter block removed. */
  readonly body: string
}

export function extractFrontmatter(raw: string): Frontmatter {
  const match = FRONTMATTER_RE.exec(raw)
  if (!match?.[1]) return { data: {}, body: raw }

  try {
    const parsed: unknown = parseYaml(match[1])
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return { data: {}, body: raw.slice(match[0].length) }
    }
    return {
      data: parsed as Record<string, unknown>,
      body: raw.slice(match[0].length),
    }
  } catch {
    return { data: {}, body: raw }
  }
}

export function firstHeading(body: string): string | null {
  const atx = /^[ \t]{0,3}#[ \t]+(.+?)[ \t]*#*[ \t]*$/m.exec(body)
  if (atx?.[1]) return atx[1].trim()

  const setext = /^[ \t]{0,3}(\S.*)\r?\n[ \t]{0,3}=+[ \t]*$/m.exec(body)
  if (setext?.[1]) return setext[1].trim()

  return null
}

function coerceOrder(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) return value
  if (typeof value === 'string') {
    const parsed = Number.parseFloat(value)
    return Number.isFinite(parsed) ? parsed : null
  }
  return null
}

function coerceTitle(value: unknown): string | null {
  return typeof value === 'string' && value.trim() !== '' ? value.trim() : null
}

export function assertWithinLimits(files: readonly WalkedFile[]): void {
  if (files.length > LIMITS.maxFiles) {
    throw new IngestError(
      `That drop contains ${files.length.toLocaleString()} files. The limit is ` +
        `${LIMITS.maxFiles.toLocaleString()} — try dropping a single folder instead.`,
      'too-many-files',
    )
  }

  const total = files.reduce((sum, f) => sum + f.file.size, 0)
  if (total > LIMITS.maxTotalBytes) {
    throw new IngestError(
      `That drop is ${formatBytes(total)}. The limit is ${formatBytes(LIMITS.maxTotalBytes)}.`,
      'too-large',
    )
  }
}

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  const units = ['KB', 'MB', 'GB']
  let value = bytes / 1024
  let unit = 0
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024
    unit++
  }
  return `${value.toFixed(value < 10 ? 1 : 0)} ${units[unit]}`
}

export interface BuildOptions {
  readonly rootName: string
}

export async function buildDocumentSet(
  files: readonly WalkedFile[],
  opts: BuildOptions,
): Promise<DocumentSet> {
  assertWithinLimits(files)

  const skipped: SkippedFile[] = []
  const markdownFiles: WalkedFile[] = []
  const imageFiles: WalkedFile[] = []

  for (const entry of files) {
    if (isMarkdownPath(entry.path)) {
      if (entry.file.size > LIMITS.maxSingleFileBytes) {
        skipped.push({
          path: entry.path,
          reason: `${formatBytes(entry.file.size)} exceeds the ${formatBytes(
            LIMITS.maxSingleFileBytes,
          )} single-file limit`,
        })
        continue
      }
      markdownFiles.push(entry)
    } else if (isImagePath(entry.path)) {
      imageFiles.push(entry)
    } else {
      skipped.push({ path: entry.path, reason: 'not a markdown or image file' })
    }
  }

  if (markdownFiles.length === 0) {
    throw new IngestError(
      files.length === 0
        ? 'Nothing was dropped.'
        : `No markdown files found among ${files.length.toLocaleString()} files. ` +
          `Looked for ${MARKDOWN_EXTENSIONS.join(', ')}.`,
      'no-markdown',
    )
  }

  const docs = await Promise.all(
    markdownFiles.map((entry) => readDoc(entry).catch((err: unknown) => failedDoc(entry, err))),
  )

  return {
    id: hashPath(`${opts.rootName}:${Date.now()}`),
    rootName: opts.rootName,
    docs: sortByReadingOrder(docs),
    assets: buildAssetMap(imageFiles),
    skipped,
    totalBytes: files.reduce((sum, f) => sum + f.file.size, 0),
    createdAt: Date.now(),
  }
}

async function readDoc(entry: WalkedFile): Promise<MarkdownDoc> {
  const raw = await entry.file.text()
  const { data, body } = extractFrontmatter(raw)

  const path = normaliseAssetPath(entry.path)
  const slash = path.lastIndexOf('/')
  const filename = slash === -1 ? path : path.slice(slash + 1)
  const dir = slash === -1 ? '' : path.slice(0, slash)
  const order = coerceOrder(data['order'])

  return {
    id: hashPath(path),
    path,
    dir,
    filename,
    title:
      coerceTitle(data['title']) ?? firstHeading(body) ?? prettifyFilename(filename),
    frontmatter: data,
    raw,
    order,
    sortKey: computeSortKey({ path, order }),
    error: null,
  }
}

function failedDoc(entry: WalkedFile, err: unknown): MarkdownDoc {
  const path = normaliseAssetPath(entry.path)
  const slash = path.lastIndexOf('/')
  const filename = slash === -1 ? path : path.slice(slash + 1)

  return {
    id: hashPath(path),
    path,
    dir: slash === -1 ? '' : path.slice(0, slash),
    filename,
    title: prettifyFilename(filename),
    frontmatter: {},
    raw: '',
    order: null,
    sortKey: computeSortKey({ path, order: null }),
    error: err instanceof Error ? err.message : 'Could not read this file',
  }
}

export function Dropzone() {
  const phase = useReader((s) => s.phase)
  const ingestDataTransfer = useReader((s) => s.ingestDataTransfer)
  const ingestFileList = useReader((s) => s.ingestFileList)

  const [dragging, setDragging] = useState(false)
  // Drag events fire for every child element, so a plain boolean flickers.
  const depth = useRef(0)
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    const onDragEnter = (e: DragEvent) => {
      if (!e.dataTransfer?.types.includes('Files')) return
      depth.current += 1
      setDragging(true)
    }
    const onDragOver = (e: DragEvent) => {
      if (!e.dataTransfer?.types.includes('Files')) return
      e.preventDefault()
      e.dataTransfer.dropEffect = 'copy'
    }
    const onDragLeave = () => {
      depth.current = Math.max(0, depth.current - 1)
      if (depth.current === 0) setDragging(false)
    }
    const onDrop = (e: DragEvent) => {
      if (!e.dataTransfer) return
      e.preventDefault()
      depth.current = 0
      setDragging(false)
      void ingestDataTransfer(e.dataTransfer)
    }

    window.addEventListener('dragenter', onDragEnter)
    window.addEventListener('dragover', onDragOver)
    window.addEventListener('dragleave', onDragLeave)
    window.addEventListener('drop', onDrop)
    return () => {
      window.removeEventListener('dragenter', onDragEnter)
      window.removeEventListener('dragover', onDragOver)
      window.removeEventListener('dragleave', onDragLeave)
      window.removeEventListener('drop', onDrop)
    }
  }, [ingestDataTransfer])

  const onPick = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) void ingestFileList(e.target.files)
      e.target.value = ''
    },
    [ingestFileList],
  )

  const busy = phase.kind === 'reading' || phase.kind === 'building'

  return (
    <div className={`dz${dragging ? ' is-dragging' : ''}`}>
      <div className="dz-plate sheet">
        <p className="dz-eyebrow">Markdown Visualiser</p>
        <h1 className="dz-title">Drop a folder of markdown.</h1>
        <p className="dz-lede">
          It is ordered, cross-linked and typeset into a single reading edition.
          Nothing is uploaded — every file stays in this browser.
        </p>

        <div className="dz-actions">
          <button
            type="button"
            className="dz-button"
            onClick={() => inputRef.current?.click()}
            disabled={busy}
          >
            {busy ? 'Reading…' : 'Choose a folder'}
          </button>
          <span className="dz-hint">or drop it anywhere on this page</span>
        </div>

        <input
          ref={inputRef}
          type="file"
          className="visually-hidden"
          multiple
          accept=".md,.markdown,.mdown,.mkd,image/*"
          // Non-standard attributes; the only way to offer a folder picker.
          {...{ webkitdirectory: '', directory: '' }}
          onChange={onPick}
          tabIndex={-1}
          aria-hidden="true"
        />

        <p className="dz-status" role="status" aria-live="polite">
          {phase.kind === 'reading' && `Reading ${phase.count} files…`}
          {phase.kind === 'building' && 'Building the index…'}
        </p>

        {phase.kind === 'error' && (
          <p className="dz-error" role="alert">
            {phase.message}
          </p>
        )}

        <dl className="dz-supports">
          <div><dt>Structure</dt><dd>Nested folders, frontmatter order, cross-links</dd></div>
          <div><dt>Content</dt><dd>GFM, callouts, math, diagrams, code</dd></div>
          <div><dt>Repair</dt><dd>Heading levels and list nesting, reported not silent</dd></div>
          <div><dt>Export</dt><dd>Print-quality PDF, or one portable HTML file</dd></div>
        </dl>
      </div>

      <div className="dz-veil" aria-hidden="true">
        <span>Release to open</span>
      </div>
    </div>
  )
}

export type LinkTarget =
  | { readonly kind: 'internal'; readonly docId: string; readonly hash: string | null }
  | { readonly kind: 'external'; readonly href: string }
  | { readonly kind: 'anchor'; readonly hash: string }
  | { readonly kind: 'missing'; readonly href: string }

export function buildDocIndex(docs: readonly MarkdownDoc[]): Map<string, string> {
  const index = new Map<string, string>()
  const ambiguous = new Set<string>()

  const add = (key: string, docId: string) => {
    const normalised = normaliseAssetPath(key)
    if (normalised === '') return
    const existing = index.get(normalised)
    if (existing !== undefined && existing !== docId) {
      ambiguous.add(normalised)
      return
    }
    index.set(normalised, docId)
  }

  for (const doc of docs) {
    add(doc.path, doc.id)
    // Links are commonly written without the extension, and directory links
    // (`../guide/`) are expected to land on that directory's index file.
    add(doc.path.replace(/\.(md|markdown|mdown|mkd)$/i, ''), doc.id)
  }

  for (const doc of docs) {
    const base = doc.filename.replace(/\.(md|markdown|mdown|mkd)$/i, '')
    if (['readme', 'index'].includes(base.toLowerCase())) {
      add(doc.dir === '' ? '.' : doc.dir, doc.id)
    }
  }

  // A key that matched two different documents cannot be resolved safely.
  for (const key of ambiguous) index.delete(key)

  return index
}

export function resolveLink(
  href: string,
  fromDoc: MarkdownDoc,
  docIndex: ReadonlyMap<string, string>,
): LinkTarget {
  const trimmed = href.trim()

  if (trimmed === '') return { kind: 'external', href }
  if (trimmed.startsWith('#')) return { kind: 'anchor', hash: trimmed.slice(1) }
  if (EXTERNAL_SCHEME.test(trimmed)) return { kind: 'external', href: trimmed }
  if (trimmed.startsWith('//')) return { kind: 'external', href: trimmed }

  const hashAt = trimmed.indexOf('#')
  const pathPart = hashAt === -1 ? trimmed : trimmed.slice(0, hashAt)
  const hash = hashAt === -1 ? null : trimmed.slice(hashAt + 1)

  if (pathPart === '') {
    return hash === null ? { kind: 'external', href } : { kind: 'anchor', hash }
  }

  const resolved = resolveRelative(fromDoc.path, pathPart)

  const direct = docIndex.get(resolved)
  if (direct !== undefined) return { kind: 'internal', docId: direct, hash }

  const withoutExt = docIndex.get(resolved.replace(/\.(md|markdown|mdown|mkd)$/i, ''))
  if (withoutExt !== undefined) return { kind: 'internal', docId: withoutExt, hash }

  const asDir = docIndex.get(resolved.replace(/\/$/, ''))
  if (asDir !== undefined) return { kind: 'internal', docId: asDir, hash }

  // Looks like a document reference but resolves to nothing in this set.
  if (/\.(md|markdown|mdown|mkd)$/i.test(pathPart)) {
    return { kind: 'missing', href: trimmed }
  }

  return { kind: 'external', href: trimmed }
}

export function makeLinkResolver(set: DocumentSet) {
  const index = buildDocIndex(set.docs)
  return (href: string, fromDoc: MarkdownDoc): LinkTarget =>
    resolveLink(href, fromDoc, index)
}

export function numericPrefix(filename: string): number | null {
  const match = /^(\d{1,6})[\s._-]/.exec(filename)
  if (!match?.[1]) return null
  return Number.parseInt(match[1], 10)
}

export function stem(filename: string): string {
  const dot = filename.lastIndexOf('.')
  return (dot > 0 ? filename.slice(0, dot) : filename).toLowerCase()
}

export function naturalKey(value: string): string {
  return value
    .toLowerCase()
    .replace(/\d+/g, (digits) => pad(Number.parseInt(digits, 10)))
}

function directoryKey(dir: string): string {
  if (dir === '') return `${pad(0, 3)}.`
  const segments = dir.split('/')
  return `${pad(segments.length, 3)}.${segments.map(naturalKey).join('/')}`
}

export interface OrderableDoc {
  /** POSIX relative path from the drop root. */
  readonly path: string
  /** Explicit `order` from YAML frontmatter, when present and numeric. */
  readonly order: number | null
}

export function computeSortKey(doc: OrderableDoc): string {
  const slash = doc.path.lastIndexOf('/')
  const dir = slash === -1 ? '' : doc.path.slice(0, slash)
  const filename = slash === -1 ? doc.path : doc.path.slice(slash + 1)
  const base = stem(filename)

  // Absent values sort last within their rank, never first.
  const explicit = doc.order === null ? pad(Number.MAX_SAFE_INTEGER) : pad(doc.order)
  const prefix = numericPrefix(filename)
  const numeric = prefix === null ? pad(Number.MAX_SAFE_INTEGER) : pad(prefix)
  const indexRank = INDEX_NAMES.has(base) ? '0' : '1'

  return [directoryKey(dir), explicit, indexRank, numeric, naturalKey(base)].join('.')
}

export function sortByReadingOrder<T extends { sortKey: string; path: string }>(
  docs: readonly T[],
): T[] {
  return [...docs].sort(
    (a, b) => a.sortKey.localeCompare(b.sortKey) || a.path.localeCompare(b.path),
  )
}

export function prettifyFilename(filename: string): string {
  const base = stem(filename).replace(/^\d{1,6}[\s._-]+/, '')
  const words = base.replace(/[-_.]+/g, ' ').trim()
  if (words === '') return stem(filename)
  return words.replace(/\b[a-z]/g, (c) => c.toUpperCase())
}

export interface WalkedFile {
  /** POSIX relative path from the drop root, e.g. `guide/img/diagram.png`. */
  readonly path: string
  readonly file: File
}

export interface WalkOptions {
  /** Abort once this many files have been collected. */
  readonly maxFiles: number
  /** Called as entries are discovered, for progress reporting. */
  readonly onProgress?: (count: number) => void
}

function readAllEntries(reader: FileSystemDirectoryReader): Promise<FileSystemEntry[]> {
  return new Promise((resolve, reject) => {
    const all: FileSystemEntry[] = []

    const readBatch = () => {
      reader.readEntries((batch) => {
        if (batch.length === 0) {
          resolve(all)
          return
        }
        all.push(...batch)
        readBatch()
      }, reject)
    }

    readBatch()
  })
}

async function walkEntry(
  entry: FileSystemEntry,
  prefix: string,
  out: WalkedFile[],
  opts: WalkOptions,
): Promise<void> {
  if (out.length >= opts.maxFiles) return
  if (isIgnoredName(entry.name)) return

  const path = prefix ? `${prefix}/${entry.name}` : entry.name

  if (entry.isFile) {
    try {
      out.push({ path, file: await entryToFile(entry as FileSystemFileEntry) })
      opts.onProgress?.(out.length)
    } catch {
      // A single unreadable file must not abort the whole import. It is
      // simply absent; docset.ts reports what it expected but did not get.
    }
    return
  }

  if (entry.isDirectory) {
    const dir = entry as FileSystemDirectoryEntry
    const children = await readAllEntries(dir.createReader())
    for (const child of children) {
      await walkEntry(child, path, out, opts)
      if (out.length >= opts.maxFiles) return
    }
  }
}

export async function walkDataTransfer(
  dt: DataTransfer,
  opts: WalkOptions,
): Promise<WalkedFile[]> {
  const out: WalkedFile[] = []

  // The DataTransferItemList is emptied when the drop event handler returns,
  // so entries must be captured synchronously before the first await.
  const entries: (FileSystemEntry | null)[] = []
  const looseFiles: File[] = []

  for (const item of Array.from(dt.items)) {
    if (item.kind !== 'file') continue
    const entry = item.webkitGetAsEntry?.() ?? null
    if (entry) {
      entries.push(entry)
    } else {
      // Browsers without the entry API still give us flat files.
      const file = item.getAsFile()
      if (file) looseFiles.push(file)
    }
  }

  for (const entry of entries) {
    if (entry) await walkEntry(entry, '', out, opts)
  }

  for (const file of looseFiles) {
    if (out.length >= opts.maxFiles) break
    if (isIgnoredName(file.name)) continue
    out.push({ path: file.name, file })
    opts.onProgress?.(out.length)
  }

  return out
}

export function walkFileList(files: FileList, opts: WalkOptions): WalkedFile[] {
  const out: WalkedFile[] = []
  for (const file of Array.from(files)) {
    if (out.length >= opts.maxFiles) break
    // webkitRelativePath is populated for directory pickers, empty otherwise.
    const rel = (file as File & { webkitRelativePath?: string }).webkitRelativePath
    const path = rel && rel.length > 0 ? rel : file.name
    if (path.split('/').some(isIgnoredName)) continue
    out.push({ path, file })
    opts.onProgress?.(out.length)
  }
  return out
}

export function stripCommonRoot(files: readonly WalkedFile[]): {
  rootName: string
  files: WalkedFile[]
} {
  if (files.length === 0) return { rootName: 'Documents', files: [] }

  const firstSegments = new Set(
    files.map((f) => (f.path.includes('/') ? f.path.slice(0, f.path.indexOf('/')) : null)),
  )

  // Only strip when every file shares one real directory prefix.
  if (firstSegments.size === 1) {
    const root = [...firstSegments][0]
    if (root) {
      return {
        rootName: root,
        files: files.map((f) => ({ ...f, path: f.path.slice(root.length + 1) })),
      }
    }
  }

  return { rootName: 'Documents', files: [...files] }
}

interface AssetOptions {
  readonly doc: MarkdownDoc
  readonly assets: ReadonlyMap<string, AssetRef>
  readonly resolveLink: (href: string, doc: MarkdownDoc) => LinkTarget
}

function figureFor(img: Element, caption: string): Element {
  return {
    type: 'element',
    tagName: 'figure',
    properties: { className: ['figure'] },
    children: [
      img,
      ...(caption === ''
        ? []
        : [
            {
              type: 'element' as const,
              tagName: 'figcaption',
              properties: {},
              children: [{ type: 'text' as const, value: caption }],
            },
          ]),
    ],
  }
}

function missingAsset(path: string): Element {
  return {
    type: 'element',
    tagName: 'div',
    properties: { className: ['asset-missing'] },
    children: [
      { type: 'element', tagName: 'span', properties: {}, children: [{ type: 'text', value: 'Image not found' }] },
      { type: 'element', tagName: 'code', properties: {}, children: [{ type: 'text', value: path }] },
    ],
  }
}

export const rehypeAssets: Plugin<[AssetOptions], Root> = (opts) => (tree: Root) => {
  // Images -----------------------------------------------------------------
  visit(tree, 'element', (node: Element, index, parent) => {
    if (node.tagName !== 'img' || index === undefined || !parent) return

    const src = node.properties?.['src']
    if (typeof src !== 'string' || src === '') return

    const alt = typeof node.properties?.['alt'] === 'string' ? node.properties['alt'] : ''

    // Absolute URLs are the author's choice; leave them alone. Data URIs are
    // narrowed to raster image types here as well as in the sanitize schema -
    // this plugin runs past the trust boundary, so it must not be capable of
    // reintroducing something the sanitizer would have rejected.
    if (/^(?:https?:|blob:)/i.test(src) || SAFE_DATA_IMAGE.test(src)) {
      parent.children[index] = figureFor(node, alt)
      return
    }

    if (/^data:/i.test(src)) {
      // A data URI that is not a raster image has no business in an <img>.
      parent.children[index] = missingAsset('unsupported inline image')
      return
    }

    const asset = lookupAsset(opts.assets, opts.doc.path, src)
    if (!asset) {
      parent.children[index] = missingAsset(src)
      return
    }

    node.properties = {
      ...node.properties,
      src: asset.url,
      loading: 'lazy',
      decoding: 'async',
    }
    parent.children[index] = figureFor(node, alt)
  })

  // Links ------------------------------------------------------------------
  visit(tree, 'element', (node: Element) => {
    if (node.tagName !== 'a') return

    const href = node.properties?.['href']
    if (typeof href !== 'string' || href === '') return

    const target = opts.resolveLink(href, opts.doc)

    switch (target.kind) {
      case 'internal':
        node.properties = {
          ...node.properties,
          href: `#${target.docId}${target.hash ? `-${target.hash}` : ''}`,
          'data-doc': target.docId,
          ...(target.hash ? { 'data-hash': target.hash } : {}),
        }
        break

      case 'anchor':
        node.properties = { ...node.properties, href: `#${target.hash}` }
        break

      case 'missing':
        node.properties = {
          ...node.properties,
          href: undefined,
          className: ['link-missing'],
          title: `Not found in this set: ${String(target.href)}`,
          'aria-disabled': 'true',
        }
        break

      case 'external':
        // Opening in a new tab needs noopener, or the target page gets a
        // handle on this window.
        node.properties = {
          ...node.properties,
          target: '_blank',
          rel: ['noopener', 'noreferrer'],
        }
        break
    }
  })
}

interface MermaidOptions {
  /** Extracted blocks are pushed here; the caller owns the array. */
  readonly sink: MermaidBlock[]
}

function hashSource(source: string): string {
  let hash = 0x811c9dc5
  for (let i = 0; i < source.length; i++) {
    hash ^= source.charCodeAt(i)
    hash = Math.imul(hash, 0x01000193) >>> 0
  }
  return hash.toString(36)
}

const isMermaidCode = (node: Element): boolean => {
  const classes = node.properties?.['className']
  return (
    Array.isArray(classes) &&
    classes.some((cls) => typeof cls === 'string' && cls === 'language-mermaid')
  )
}

export const rehypeMermaid: Plugin<[MermaidOptions], Root> = ({ sink }) =>
  (tree: Root) => {
    visit(tree, 'element', (node: Element, index, parent) => {
      if (node.tagName !== 'pre' || index === undefined || !parent) return

      const code = node.children.find(
        (child): child is Element => child.type === 'element' && child.tagName === 'code',
      )
      if (!code || !isMermaidCode(code)) return

      const source = hastToString(code).trim()
      if (source === '') return

      // Two identical diagrams in one document share an id, which is correct:
      // identical source produces identical output and Mermaid's cache is a
      // help rather than a hazard in that case.
      const id = `mmd-${hashSource(source)}`
      if (!sink.some((block) => block.id === id)) sink.push({ id, code: source })

      const placeholder: Element = {
        type: 'element',
        tagName: 'figure',
        properties: {
          className: ['mermaid-figure'],
          id,
          // The source travels with the element so the export path can
          // recover it without consulting the render result.
          'data-mermaid': id,
        },
        children: [
          {
            type: 'element',
            tagName: 'div',
            properties: { className: ['mermaid-slot'] },
            children: [
              // Fallback content: if the diagram never renders - Mermaid failed
              // to load, or the syntax is invalid - the reader still sees the
              // source rather than an empty gap.
              {
                type: 'element',
                tagName: 'pre',
                properties: { className: ['mermaid-source'] },
                children: [{ type: 'text', value: source }],
              },
            ],
          },
        ],
      }

      parent.children[index] = placeholder
    })
  }

export function getHighlighter(): Promise<HighlighterCore> {
  highlighterPromise ??= (async () => {
    const [{ createHighlighterCore }, { createJavaScriptRegexEngine }] = await Promise.all([
      import('shiki/core'),
      import('shiki/engine/javascript'),
    ])

    return createHighlighterCore({
      themes: [
        import('shiki/themes/github-light.mjs'),
        import('shiki/themes/github-dark.mjs'),
      ],
      langs: EAGER_LANGUAGES.map((lang) => LANG_LOADERS[lang]!()),
      engine: createJavaScriptRegexEngine({ forgiving: true }),
    })
  })()

  return highlighterPromise
}

function fenceLabel(node: Element): string | null {
  const classes = node.properties?.['className']
  if (!Array.isArray(classes)) return null
  for (const cls of classes) {
    if (typeof cls !== 'string') continue
    if (cls.startsWith('language-')) return cls.slice('language-'.length).toLowerCase()
  }
  return null
}

export function collectLanguages(tree: Root): string[] {
  const found = new Set<string>()
  visit(tree, 'element', (node: Element, _i, parent) => {
    if (node.tagName !== 'code') return
    if ((parent as Element | undefined)?.tagName !== 'pre') return
    const label = fenceLabel(node)
    if (label === null || label === 'mermaid') return
    const canonical = resolveLanguage(label)
    if (canonical !== null) found.add(canonical)
  })
  return [...found]
}

export async function ensureLanguages(
  highlighter: HighlighterCore,
  languages: readonly string[],
): Promise<void> {
  const loaded = new Set(highlighter.getLoadedLanguages())
  const missing = languages.filter((lang) => !loaded.has(lang) && lang in LANG_LOADERS)

  await Promise.all(
    missing.map(async (lang) => {
      try {
        await highlighter.loadLanguage((await LANG_LOADERS[lang]!()) as never)
      } catch {
        // A grammar that fails to load leaves its block unhighlighted, which
        // is a cosmetic loss rather than a broken document.
      }
    }),
  )
}

interface ShikiOptions {
  readonly highlighter: HighlighterCore
}

export const rehypeShiki: Plugin<[ShikiOptions], Root> = ({ highlighter }) =>
  (tree: Root) => {
    const loaded = new Set(highlighter.getLoadedLanguages())

    visit(tree, 'element', (node: Element, index, parent) => {
      if (node.tagName !== 'pre') return
      const code = node.children.find(
        (child): child is Element => child.type === 'element' && child.tagName === 'code',
      )
      if (!code || index === undefined || !parent) return

      const label = fenceLabel(code)
      if (label === null || label === 'mermaid') return

      const lang = resolveLanguage(label)
      if (lang === null || !loaded.has(lang)) return

      try {
        const html = highlighter.codeToHtml(hastToString(code), {
          lang,
          themes: THEMES,
          // CSS variables rather than two full colour sets, so the
          // stylesheet decides which theme applies.
          defaultColor: false,
          cssVariablePrefix: '--shiki-',
        })

        // codeToHtml returns a complete <pre>; splice it in as raw HTML. This
        // is past the trust boundary and is our own generated output.
        parent.children[index] = { type: 'raw', value: html } as unknown as Element
      } catch {
        // Highlighting is decoration. A grammar that throws leaves the
        // original block in place rather than losing the code.
      }
    })
  }

export interface RepairResult {
  readonly notes: RepairNote[]
}

interface RepairOptions {
  /** Collected notes are pushed here; the caller owns the array. */
  readonly sink: RepairNote[]
  /**
   * The document title as resolved by ingest, which the reader already shows
   * in its own title block. A leading H1 repeating it is printed twice.
   */
  readonly title?: string
}

function dropRedundantTitle(tree: Root, opts: RepairOptions): void {
  if (opts.title === undefined) return

  // Skip the frontmatter node, which is the document's first child when
  // present. Only 'yaml' is enabled on remark-frontmatter in this pipeline.
  const index = tree.children.findIndex((node) => node.type !== 'yaml')
  const first = index === -1 ? undefined : tree.children[index]
  if (!first || first.type !== 'heading' || first.depth !== 1) return

  const text = mdastToString(first)
  if (!sameTitle(text, opts.title)) return

  tree.children.splice(index, 1)
  opts.sink.push({
    rule: 'duplicate-h1',
    line: lineOf(first),
    before: `h1: ${text}`,
    after: 'shown once, in the document header',
    detail: 'This heading repeated the document title, so it was not printed twice.',
  })
}

function repairHeadings(tree: Root, opts: RepairOptions): void {
  const headings: Heading[] = []
  visit(tree, 'heading', (node: Heading) => {
    headings.push(node)
  })
  if (headings.length === 0) return

  /** Input depths already seen, mapped to the depth we emitted for them. */
  const stack: { input: number; output: number }[] = []
  let seenH1 = false

  for (const node of headings) {
    const input = node.depth
    const text = mdastToString(node)

    // Drop entries deeper than or equal to this heading: they are siblings
    // or children of a section this heading now closes.
    while (stack.length > 0 && stack[stack.length - 1]!.input >= input) stack.pop()

    const parent = stack[stack.length - 1]
    let output: number

    if (input === 1) {
      if (!seenH1) {
        seenH1 = true
        output = 1
      } else {
        // A second competing title. Demote it under the first.
        output = 2
        opts.sink.push({
          rule: 'duplicate-h1',
          line: lineOf(node),
          before: `h1: ${text}`,
          after: `h2: ${text}`,
          detail:
            'The document already had a top-level heading, so this one was ' +
            'demoted to keep a single title.',
        })
      }
    } else if (!parent) {
      // A heading deeper than h1 with no ancestor - e.g. a file that opens
      // on an h3. Promote it to the top level of its own hierarchy.
      output = seenH1 ? 2 : 1
      if (output !== input) {
        opts.sink.push({
          rule: 'heading-skip',
          line: lineOf(node),
          before: `h${input}: ${text}`,
          after: `h${output}: ${text}`,
          detail: 'This heading had no parent section, so it was promoted.',
        })
      }
    } else {
      // Exactly one level below the parent's *output* depth, not its input
      // depth. Deriving from the output is what makes a demoted section carry
      // its whole subtree down with it: if `# B` became an h2, then `## B1`
      // beneath it must become an h3, or B1 ends up a sibling of the section
      // it belongs to and the index shows a structure the document does not
      // have. The stack has already popped everything at or below this
      // heading's input depth, so the parent is always genuinely shallower.
      output = parent.output + 1
      if (output !== input) {
        opts.sink.push({
          rule: 'heading-skip',
          line: lineOf(node),
          before: `h${input}: ${text}`,
          after: `h${output}: ${text}`,
          detail:
            output < input
              ? `Jumped from h${parent.output} to h${input}, skipping a level.`
              : 'Shifted to stay beneath its parent section, which moved.',
        })
      }
    }

    node.depth = Math.min(6, Math.max(1, output)) as Heading['depth']
    // Any heading that ends up at depth 1 is the document's title, however it
    // got there. Tracking this only in the `input === 1` branch left a
    // *promoted* heading unrecorded, so a later genuine h1 was not demoted and
    // the document rendered with two competing titles.
    if (node.depth === 1) seenH1 = true
    stack.push({ input, output: node.depth })
  }
}

function repairLists(tree: Root, opts: RepairOptions): void {
  visit(tree, 'list', (node: List) => {
    const items = node.children
    if (items.length < 2) return

    const spreadCount = items.filter((item) => item.spread === true).length
    const dominant = spreadCount > items.length / 2

    const inconsistent = items.some((item) => (item.spread === true) !== dominant)
    if (!inconsistent) return

    for (const item of items) item.spread = dominant
    node.spread = dominant

    opts.sink.push({
      rule: 'mixed-markers',
      line: lineOf(node),
      before: `${spreadCount} of ${items.length} items spaced apart`,
      after: dominant ? 'all items spaced apart' : 'all items tight',
      detail: 'List items disagreed about spacing, which broke the rhythm.',
    })
  })
}

function repairListNesting(tree: Root, opts: RepairOptions): void {
  visit(tree, 'listItem', (item) => {
    const kids = item.children
    // A list item whose only child is a list has lost its own text content to
    // an indentation mistake; unwrap it so the levels line up.
    if (kids.length === 1 && kids[0]?.type === 'list') {
      const inner = kids[0] as List
      if (inner.children.length > 0) {
        item.children = inner.children.flatMap((child) => child.children)
        opts.sink.push({
          rule: 'list-nesting',
          line: lineOf(item),
          before: 'list item containing only a nested list',
          after: 'nested items lifted to this level',
          detail: 'Indentation created an empty level of nesting.',
        })
      }
    }
  })
}

function reportUnbalancedEmphasis(tree: Root, opts: RepairOptions): void {
  visit(tree, 'text', (node) => {
    const stray = /(\*\*|__)(?![\s\S]*\1)/.exec(node.value)
    if (!stray) return
    opts.sink.push({
      rule: 'unbalanced-emphasis',
      line: lineOf(node),
      before: node.value.slice(0, 60),
      after: 'rendered literally',
      detail:
        `An unclosed ${stray[1]} was left as text. It was probably meant to ` +
        'be bold.',
    })
  })
}

export const remarkRepair: Plugin<[RepairOptions], Root> = (opts) => (tree: Root) => {
  // Order matters: emphasis is reported against the original text, while
  // headings and lists rewrite structure.
  reportUnbalancedEmphasis(tree, opts)
  // Before repairHeadings, so the hierarchy is normalised against what will
  // actually be rendered rather than against a heading about to be removed.
  dropRedundantTitle(tree, opts)
  repairHeadings(tree, opts)
  repairListNesting(tree, opts)
  repairLists(tree, opts)
}

export function resolveLanguage(label: string): string | null {
  const lower = label.toLowerCase()
  const canonical = ALIASES[lower] ?? lower
  return canonical in LANG_LOADERS ? canonical : null
}

export interface RenderContext {
  readonly assets: ReadonlyMap<string, AssetRef>
  readonly resolveLink: (href: string, doc: MarkdownDoc) => LinkTarget
}

function headingPlugin(sink: Heading[]) {
  return () => (tree: HastRoot) => {
    const slugger = new GithubSlugger()
    const flat: Heading[] = []

    visit(tree, 'element', (node: Element) => {
      const match = /^h([1-6])$/.exec(node.tagName)
      if (!match?.[1]) return

      const text = hastToString(node).trim()
      if (text === '') return

      const existing = node.properties?.['id']
      const id = typeof existing === 'string' && existing !== '' ? existing : slugger.slug(text)
      node.properties = { ...node.properties, id }

      flat.push({ id, depth: Number(match[1]), text, children: [] })
    })

    // Nest by depth. The repair pass has already guaranteed no level is
    // skipped, so a simple stack is sufficient and cannot mis-nest.
    const stack: Heading[] = []
    for (const heading of flat) {
      while (stack.length > 0 && stack[stack.length - 1]!.depth >= heading.depth) stack.pop()
      const parent = stack[stack.length - 1]
      if (parent) parent.children.push(heading)
      else sink.push(heading)
      stack.push(heading)
    }
  }
}

function tableWrapPlugin() {
  return () => (tree: HastRoot) => {
    visit(tree, 'element', (node: Element, index, parent) => {
      if (node.tagName !== 'table' || index === undefined || !parent) return
      if ((parent as Element).properties?.['className']?.toString().includes('table-wrap')) return

      parent.children[index] = {
        type: 'element',
        tagName: 'div',
        properties: { className: ['table-wrap'], tabIndex: 0, role: 'region' },
        children: [node],
      }
    })
  }
}

function openingParagraphPlugin() {
  return () => (tree: HastRoot) => {
    for (const node of tree.children) {
      if (node.type !== 'element') continue
      if (node.tagName === 'p') {
        node.properties = {
          ...node.properties,
          className: [
            ...(Array.isArray(node.properties?.['className'])
              ? (node.properties['className'] as string[])
              : []),
            'opening',
          ],
        }
        return
      }
      // A heading before the first paragraph is fine; anything else means
      // the document does not open on prose and gets no drop cap.
      if (!/^h[1-6]$/.test(node.tagName)) return
    }
  }
}

export async function renderDocument(
  doc: MarkdownDoc,
  ctx: RenderContext,
): Promise<RenderResult> {
  if (doc.error !== null) {
    return {
      docId: doc.id,
      html: '',
      headings: [],
      repairs: [],
      mermaidBlocks: [],
      wordCount: 0,
      readingMinutes: 0,
    }
  }

  const repairs: RepairNote[] = []
  const headings: Heading[] = []
  const mermaidBlocks: MermaidBlock[] = []

  // Shiki needs its grammars before the synchronous visitor runs, so the
  // document is parsed once up front purely to discover which languages it
  // uses. Cheaper than shipping every grammar.
  const highlighter = await getHighlighter()
  const discovery = unified()
    .use(remarkParse)
    .use(remarkFrontmatter, ['yaml'])
    .use(remarkGfm)
    .use(remarkRehype, { allowDangerousHtml: true })
    .runSync(unified().use(remarkParse).parse(doc.raw) as MdastRoot) as HastRoot
  await ensureLanguages(highlighter, collectLanguages(discovery))

  const file = await unified()
    .use(remarkParse)
    // Frontmatter first: it must be recognised before any other plugin can
    // mistake the --- fence for a thematic break.
    .use(remarkFrontmatter, ['yaml'])
    .use(remarkGfm)
    .use(remarkMath)
    .use(remarkRepair, { sink: repairs, title: doc.title })
    .use(remarkAlert)
    .use(remarkRehype, { allowDangerousHtml: true })
    .use(rehypeRaw)
    // ---- TRUST BOUNDARY. Nothing user-controlled may be added below. ----
    .use(rehypeSanitize, sanitizeSchema)
    // rehype-katex omits throwOnError from its options deliberately: it
    // always renders a parse error inline rather than throwing, which is
    // the behaviour we want for arbitrary dropped documents.
    .use(rehypeKatex)
    .use(rehypeShiki, { highlighter })
    .use(rehypeMermaid, { sink: mermaidBlocks })
    .use(rehypeAssets, { doc, assets: ctx.assets, resolveLink: ctx.resolveLink })
    .use(headingPlugin(headings))
    .use(tableWrapPlugin())
    .use(openingParagraphPlugin())
    .use(rehypeStringify, { allowDangerousHtml: true })
    .process(doc.raw)

  const wordCount = doc.raw.split(/\s+/).filter((w) => /[\p{L}\p{N}]/u.test(w)).length

  return {
    docId: doc.id,
    html: String(file),
    headings,
    repairs,
    mermaidBlocks,
    wordCount,
    readingMinutes: Math.max(1, Math.round(wordCount / WORDS_PER_MINUTE)),
  }
}

const inherited = (tag: string): PropertyDefinition[] => [
  ...(base.attributes?.[tag] ?? []),
]

const inheritedExcept = (tag: string, drop: readonly string[]): PropertyDefinition[] =>
  inherited(tag).filter((def) => {
    const name = typeof def === 'string' ? def : def[0]
    return !drop.includes(name)
  })

export const sanitizeSchema: SanitizeSchema = {
  ...base,

  tagNames: [
    ...(base.tagNames ?? []),
    // GFM tables and footnotes need the full table set plus <section>.
    'section',
    // Figures are how images are presented; the default schema omits them.
    'figure',
    'figcaption',
  ],

  attributes: {
    ...base.attributes,

    // Heading anchors, footnote targets and callout wrappers all need ids.
    '*': [...inherited('*'), 'id', 'className'],

    code: [...inherited('code'), classes(CODE_LANGUAGE_PATTERN, ...MATH_CLASSES)],
    pre: [...inherited('pre'), classes(CODE_LANGUAGE_PATTERN, 'mermaid')],
    span: [...inherited('span'), classes(...MATH_CLASSES)],
    div: [...inherited('div'), classes(...MATH_CLASSES, ...ALERT_CLASSES)],
    p: [...inherited('p'), classes(...ALERT_CLASSES)],
    blockquote: [...inherited('blockquote'), classes(...ALERT_CLASSES)],

    // Relative image paths are rewritten to blob URLs after sanitization, so
    // src must survive - but as an explicit value allowlist, not a bare
    // 'src'. A scheme-only check passes `data:text/html;base64,<script>`,
    // because the sanitizer validates the scheme and not the media type.
    // Listing the permitted shapes is what actually closes that.
    img: [
      ...inheritedExcept('img', ['src', 'srcSet', 'srcset']),
      [
        'src',
        /^https?:\/\//i,
        /^blob:/i,
        // Raster data URIs only. SVG is excluded: it is a document format
        // that can carry script, and nothing needs it inlined here.
        /^data:image\/(?:png|jpeg|jpg|gif|webp|avif|bmp);/i,
        // Relative paths, resolved against the asset map downstream.
        /^(?!\w+:)[^\s]+$/,
      ] as PropertyDefinition,
      'alt',
      'title',
      'width',
      'height',
      'loading',
    ],
    a: [...inherited('a'), 'href', 'title', 'id', 'dataFootnoteRef', 'ariaDescribedby'],

    // Task list checkboxes. Values are pinned, so nothing else gets through.
    input: [
      ['type', 'checkbox'] as PropertyDefinition,
      ['disabled', true] as PropertyDefinition,
      ['checked', true] as PropertyDefinition,
    ],

    th: [...inherited('th'), 'colSpan', 'rowSpan'],
    td: [...inherited('td'), 'colSpan', 'rowSpan'],
  },

  // Only these schemes may appear in a URL attribute. This is what stops
  // `javascript:`, `vbscript:` and `data:text/html` payloads.
  protocols: {
    ...base.protocols,
    href: ['http', 'https', 'mailto', 'tel', 'irc', 'ircs', 'xmpp'],
    // Belt and braces with the img value allowlist above: this rejects the
    // scheme, that rejects the media type.
    src: ['http', 'https', 'blob', 'data'],
  },

  // Never allowed, whatever the markdown says. Listing them explicitly rather
  // than relying on the default is deliberate: it documents the intent and
  // survives a future change to the upstream default schema.
  strip: ['script', 'style', 'iframe', 'object', 'embed', 'link', 'meta', 'base', 'form'],

  clobberPrefix: 'user-content-',
  clobber: ['name', 'id'],
}

export const printSchema: SanitizeSchema = {
  ...sanitizeSchema,
  // The print context loads no subresources at all, so remote URLs have no
  // legitimate purpose. Only inlined data and blob URLs remain.
  protocols: {
    href: ['http', 'https', 'mailto'],
    src: ['data', 'blob'],
  },
}

export function DocumentView({
  doc,
  result,
  index,
  total,
  onNavigate,
  onImageOpen,
}: DocumentViewProps) {
  const root = useRef<HTMLDivElement>(null)

  useMermaid(root, result.mermaidBlocks, result.html)

  /**
   * Replace an image that fails to decode with the same styled placeholder a
   * missing path gets.
   *
   * The pipeline can only check that a path *resolves*; a file that resolves
   * but is truncated, or is not really an image, still fails at decode time
   * and the browser draws its own broken-image icon. Listening in the capture
   * phase is required because `error` does not bubble.
   */
  useEffect(() => {
    const node = root.current
    if (!node) return

    const onError = (event: Event) => {
      const img = event.target
      if (!(img instanceof HTMLImageElement)) return

      const figure = img.closest('figure')
      const replacement = document.createElement('div')
      replacement.className = 'asset-missing'
      const label = document.createElement('span')
      label.textContent = 'Image could not be displayed'
      const path = document.createElement('code')
      path.textContent = img.getAttribute('alt') || 'unnamed image'
      replacement.append(label, path)
      ;(figure ?? img).replaceWith(replacement)
    }

    node.addEventListener('error', onError, true)
    return () => node.removeEventListener('error', onError, true)
  }, [result.html])

  // Intercept in-document clicks: cross-document links become navigation,
  // and images open in the lightbox.
  useEffect(() => {
    const node = root.current
    if (!node) return

    const onClick = (event: MouseEvent) => {
      const target = event.target as HTMLElement | null
      if (!target) return

      const link = target.closest('a[data-doc]')
      if (link) {
        event.preventDefault()
        onNavigate(
          link.getAttribute('data-doc') ?? '',
          link.getAttribute('data-hash'),
        )
        return
      }

      const img = target.closest('figure img')
      if (img instanceof HTMLImageElement) {
        event.preventDefault()
        onImageOpen(img.src, img.alt)
      }
    }

    node.addEventListener('click', onClick)
    return () => node.removeEventListener('click', onClick)
  }, [onNavigate, onImageOpen])

  const frontmatterEntries = useMemo(
    () =>
      Object.entries(doc.frontmatter)
        .filter(([key]) => !['title', 'order'].includes(key))
        .filter(([, value]) => typeof value === 'string' || typeof value === 'number')
        .slice(0, 6),
    [doc.frontmatter],
  )

  return (
    <article className="doc" aria-labelledby={`doc-title-${doc.id}`}>
      <header className="doc-head">
        <p className="doc-eyebrow">
          <span>{doc.path}</span>
          <span aria-hidden="true">·</span>
          <span>
            {result.readingMinutes} min · {result.wordCount.toLocaleString()} words
          </span>
        </p>
        <h1 className="doc-title" id={`doc-title-${doc.id}`}>
          {doc.title}
        </h1>

        {frontmatterEntries.length > 0 && (
          <dl className="doc-frontmatter">
            {frontmatterEntries.map(([key, value]) => (
              <div key={key}>
                <dt>{key}</dt>
                <dd>{String(value)}</dd>
              </div>
            ))}
          </dl>
        )}
      </header>

      {result.repairs.length > 0 && <RepairNotice repairs={result.repairs} />}

      {doc.error !== null ? (
        <p className="doc-failed" role="alert">
          This file could not be read: {doc.error}
        </p>
      ) : (
        <Prose html={result.html} rootRef={root} />
      )}

      <footer className="doc-folio" aria-hidden="true">
        <span>{doc.title}</span>
        <span className="doc-folio-rule" />
        <span>
          {index + 1} / {total}
        </span>
      </footer>
    </article>
  )
}

type State =
  | { readonly kind: 'idle' }
  | { readonly kind: 'working'; readonly what: string }
  | { readonly kind: 'error'; readonly message: string }

export function ExportBar({ set }: { readonly set: DocumentSet }) {
  const [state, setState] = useState<State>({ kind: 'idle' })

  /** Render every document, so the export contains the whole set. */
  const renderAll = useCallback(async (): Promise<RenderResult[]> => {
    const results: RenderResult[] = []
    for (const doc of set.docs) {
      if (doc.error !== null) continue
      results.push(await renderDoc(set, doc))
    }
    return results
  }, [set])

  const exportHtml = useCallback(async () => {
    setState({ kind: 'working', what: 'Building a self-contained file' })
    try {
      const results = await renderAll()
      const html = await buildStandalone({ set, results })
      downloadStandalone(html, safeFilename(set.rootName, 'html'))
      setState({ kind: 'idle' })
    } catch (err) {
      setState({
        kind: 'error',
        message: err instanceof Error ? err.message : 'The export failed.',
      })
    }
  }, [set, renderAll])

  const exportPdf = useCallback(async () => {
    setState({ kind: 'working', what: 'Typesetting for print' })
    try {
      const results = await renderAll()
      const html = await buildStandalone({ set, results })
      const blob = await requestPdf({ html, title: set.rootName })
      downloadBlob(blob, safeFilename(set.rootName, 'pdf'))
      setState({ kind: 'idle' })
    } catch (err) {
      setState({
        kind: 'error',
        message: err instanceof Error ? err.message : 'The export failed.',
      })
    }
  }, [set, renderAll])

  const busy = state.kind === 'working'

  return (
    <div className="export-bar">
      <button type="button" onClick={() => void exportPdf()} disabled={busy}>
        PDF
      </button>
      <button type="button" onClick={() => void exportHtml()} disabled={busy}>
        HTML
      </button>

      <span className="export-status" role="status" aria-live="polite">
        {busy && `${state.what}…`}
      </span>

      {state.kind === 'error' && (
        <span className="export-error" role="alert">
          {state.message}
        </span>
      )}
    </div>
  )
}

interface IndexSidebarProps {
  readonly set: DocumentSet
  readonly activeDoc: MarkdownDoc
  readonly headings: readonly Heading[]
  readonly onOpenDoc: (docId: string) => void
}

export function IndexSidebar({ set, activeDoc, headings, onOpenDoc }: IndexSidebarProps) {
  const activeHeading = useActiveHeading(headings)

  // Group documents by directory so nested sections read as sections.
  const groups = useMemo(() => {
    const out: { dir: string; docs: MarkdownDoc[] }[] = []
    for (const doc of set.docs) {
      const last = out[out.length - 1]
      if (last && last.dir === doc.dir) last.docs.push(doc)
      else out.push({ dir: doc.dir, docs: [doc] })
    }
    return out
  }, [set.docs])

  return (
    <nav className="index" aria-label="Contents">
      <div className="index-head">
        <p className="index-eyebrow">Contents</p>
        <p className="index-root">{set.rootName}</p>
      </div>

      <ol className="index-docs">
        {groups.map((group) => (
          <li key={group.dir || '.'} className="index-group">
            {group.dir !== '' && <p className="index-dir">{group.dir}</p>}
            <ol className="index-group-docs">
              {group.docs.map((doc) => {
                const isActive = doc.id === activeDoc.id
                return (
                  <li key={doc.id}>
                    <a
                      href={`#${doc.id}`}
                      className={`index-doc${isActive ? ' is-active' : ''}${
                        doc.error ? ' is-failed' : ''
                      }`}
                      aria-current={isActive ? 'page' : undefined}
                      onClick={(e) => {
                        e.preventDefault()
                        onOpenDoc(doc.id)
                      }}
                    >
                      <span className="index-marker" aria-hidden="true">
                        {isActive ? '●' : '○'}
                      </span>
                      <span className="index-doc-title">{doc.title}</span>
                    </a>

                    {/* The open document expands into its own heading tree. */}
                    {isActive && headings.length > 0 && (
                      <HeadingTree
                        headings={headings}
                        activeId={activeHeading}
                        depth={0}
                      />
                    )}
                  </li>
                )
              })}
            </ol>
          </li>
        ))}
      </ol>

      {set.skipped.length > 0 && (
        <details className="index-skipped">
          <summary>{set.skipped.length} files skipped</summary>
          <ul>
            {set.skipped.slice(0, 20).map((s) => (
              <li key={s.path}>
                <code>{s.path}</code>
                <span>{s.reason}</span>
              </li>
            ))}
          </ul>
        </details>
      )}
    </nav>
  )
}

function HeadingTree({
  headings,
  activeId,
  depth,
}: {
  readonly headings: readonly Heading[]
  readonly activeId: string | null
  readonly depth: number
}) {
  // Beyond three levels the sidebar becomes a wall of text rather than a map.
  if (depth > 2) return null

  return (
    <ul className="index-headings" data-depth={depth}>
      {headings.map((heading) => (
        <li key={heading.id}>
          <a
            href={`#${heading.id}`}
            className={`index-heading${heading.id === activeId ? ' is-active' : ''}`}
            aria-current={heading.id === activeId ? 'true' : undefined}
          >
            {heading.text}
          </a>
          {heading.children.length > 0 && (
            <HeadingTree
              headings={heading.children}
              activeId={activeId}
              depth={depth + 1}
            />
          )}
        </li>
      ))}
    </ul>
  )
}

function flatten(headings: readonly Heading[]): Heading[] {
  return headings.flatMap((h) => [h, ...flatten(h.children)])
}

function useActiveHeading(headings: readonly Heading[]): string | null {
  const [active, setActive] = useState<string | null>(null)
  const visible = useRef(new Set<string>())

  useEffect(() => {
    const flat = flatten(headings)
    if (flat.length === 0) {
      setActive(null)
      return
    }

    visible.current.clear()
    const order = new Map(flat.map((h, i) => [h.id, i]))

    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          const id = entry.target.id
          if (entry.isIntersecting) visible.current.add(id)
          else visible.current.delete(id)
        }

        // The topmost visible heading in document order is the current one.
        let best: string | null = null
        let bestIndex = Number.POSITIVE_INFINITY
        for (const id of visible.current) {
          const index = order.get(id) ?? Number.POSITIVE_INFINITY
          if (index < bestIndex) {
            bestIndex = index
            best = id
          }
        }

        // Nothing intersecting means the reader is mid-section, between two
        // headings: keep the last one rather than clearing the highlight.
        if (best !== null) setActive(best)
      },
      { rootMargin: '-25% 0px -65% 0px', threshold: 0 },
    )

    const targets = flat
      .map((h) => document.getElementById(h.id))
      .filter((el): el is HTMLElement => el !== null)

    for (const el of targets) observer.observe(el)
    setActive(flat[0]?.id ?? null)

    return () => observer.disconnect()
  }, [headings])

  return active
}

interface LightboxProps {
  readonly src: string
  readonly alt: string
  readonly onClose: () => void
}

export function Lightbox({ src, alt, onClose }: LightboxProps) {
  const closeButton = useRef<HTMLButtonElement>(null)
  const returnFocusTo = useRef<Element | null>(null)

  useEffect(() => {
    returnFocusTo.current = document.activeElement
    closeButton.current?.focus()

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault()
        onClose()
        return
      }
      // Only one focusable element, so Tab must simply stay on it rather
      // than escaping to the document behind the overlay.
      if (event.key === 'Tab') {
        event.preventDefault()
        closeButton.current?.focus()
      }
    }

    document.addEventListener('keydown', onKeyDown)
    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'

    return () => {
      document.removeEventListener('keydown', onKeyDown)
      document.body.style.overflow = previousOverflow
      if (returnFocusTo.current instanceof HTMLElement) returnFocusTo.current.focus()
    }
  }, [onClose])

  return (
    <div
      className="lightbox"
      role="dialog"
      aria-modal="true"
      aria-label={alt === '' ? 'Image' : alt}
      onClick={(e) => {
        // Clicking the backdrop closes; clicking the image itself does not.
        if (e.target === e.currentTarget) onClose()
      }}
    >
      <button ref={closeButton} type="button" className="lightbox-close" onClick={onClose}>
        Close
        <span aria-hidden="true"> ✕</span>
      </button>

      <figure className="lightbox-figure">
        <img src={src} alt={alt} />
        {alt !== '' && <figcaption>{alt}</figcaption>}
      </figure>
    </div>
  )
}

function loadMermaid(): Promise<MermaidApi> {
  // Caching the promise is what makes initialize() run exactly once. Caching a
  // *rejected* one would be permanent, though: the chunk is ~3MB, so a reader
  // who navigates away mid-download aborts the fetch, and every later document
  // would then reuse that failure and silently show diagram source forever.
  // On failure the slot is cleared so the next attempt genuinely retries.
  mermaidReady ??= import('mermaid')
    .catch((err: unknown) => {
      mermaidReady = null
      throw err instanceof Error ? err : new Error(String(err))
    })
    .then(({ default: mermaid }) => {
      mermaid.initialize({
        // We call render() explicitly, so the library must not also scan the
        // document on load and race us for the same elements.
        startOnLoad: false,
        // Diagram source comes from arbitrary dropped files. 'strict' encodes
        // HTML in labels and disables click bindings; 'loose' allows both.
        securityLevel: 'strict',
        theme: 'base',
        fontFamily: "'Newsreader', Georgia, serif",
        themeVariables: {
          // Matched to the paper surface, so a diagram sits on the page rather
          // than looking like something pasted onto it.
          background: '#f5efe1',
          primaryColor: '#eee6d4',
          primaryTextColor: '#2a241d',
          primaryBorderColor: '#6d6154',
          lineColor: '#6d6154',
          secondaryColor: '#e6dcc6',
          tertiaryColor: '#faf6ec',
          mainBkg: '#faf6ec',
          nodeBorder: '#6d6154',
          clusterBkg: '#eee6d4',
          clusterBorder: '#ddd2ba',
          titleColor: '#17120d',
          edgeLabelBackground: '#f5efe1',
          fontSize: '15px',
        },
      })
      return mermaid
    })

  return mermaidReady
}

export function whenDiagramsSettled(): Promise<void> {
  return Promise.allSettled([...inflight]).then(() => undefined)
}

function currentSlot(host: HTMLElement, id: string): HTMLElement | null {
  return host.querySelector<HTMLElement>(
    `[data-mermaid="${CSS.escape(id)}"] .mermaid-slot`,
  )
}

function svgFragment(svg: string): DocumentFragment {
  return document.createRange().createContextualFragment(svg)
}

function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('mermaid render timed out')), ms)
    promise.then(
      (value) => {
        clearTimeout(timer)
        resolve(value)
      },
      (err: unknown) => {
        clearTimeout(timer)
        reject(err instanceof Error ? err : new Error(String(err)))
      },
    )
  })
}

export async function drawDiagramsIn(
  root: HTMLElement,
  blocks: readonly MermaidBlock[],
): Promise<void> {
  if (blocks.length === 0) return

  const byId = new Map(blocks.map((b) => [b.id, b.code]))
  const targets = [...root.querySelectorAll<HTMLElement>('[data-mermaid]')].flatMap((figure) => {
    const id = figure.getAttribute('data-mermaid')
    const code = id === null ? undefined : byId.get(id)
    const slot = figure.querySelector<HTMLElement>('.mermaid-slot')
    // A slot already carrying a diagram was drawn by an earlier pass.
    if (!id || !code || !slot || slot.classList.contains('is-drawn')) return []
    return [{ id, code, slot }]
  })
  if (targets.length === 0) return

  let mermaid: MermaidApi
  try {
    mermaid = await withTimeout(loadMermaid(), RENDER_TIMEOUT_MS)
  } catch {
    // Mark the slots so the failure is visible rather than looking like a
    // diagram that simply never arrived. The source stays readable.
    for (const { slot } of targets) slot.classList.add('is-failed')
    return
  }

  for (const { id, code, slot } of targets) {
    // A fresh id per call. Mermaid caches SVG defs by id, so reusing one
    // across changed source yields a stale or broken diagram.
    const renderId = `${id}-${Math.random().toString(36).slice(2, 8)}`
    try {
      const { svg } = await withTimeout(mermaid.render(renderId, code), RENDER_TIMEOUT_MS)
      // Re-query rather than reusing the node captured before the await: a
      // node reference held across an await may no longer be in the document,
      // and writing into a detached one fails silently.
      const current = currentSlot(root, id) ?? slot
      current.replaceChildren(svgFragment(svg))
      current.classList.add('is-drawn')
    } catch {
      const current = currentSlot(root, id) ?? slot
      // Mark it, so a later pass does not retry indefinitely and the reader
      // is left with the source rather than an empty frame.
      current.classList.add('is-failed')
    }
  }
}

export function useMermaid(
  root: RefObject<HTMLElement | null>,
  blocks: readonly MermaidBlock[],
  /**
   * The rendered HTML currently injected into `root`.
   *
   * Required as a dependency, not a convenience: navigating away and back to
   * the same document replaces the DOM with a fresh copy of this string while
   * `blocks` keeps its cached identity. Without it the effect does not re-run,
   * the freshly injected placeholders are never drawn, and the reader sees the
   * diagram source instead of the diagram.
   */
  htmlKey: string,
): void {
  useEffect(() => {
    const host = root.current
    if (!host || blocks.length === 0) return

    // No cancellation flag: the draw re-queries its target before every write
    // and skips slots already marked, so an unmounted effect writes into a
    // node that is no longer in the document and is harmlessly inert.
    const job = drawDiagramsIn(host, blocks)
    inflight.add(job)
    void job.finally(() => inflight.delete(job))
  }, [root, blocks, htmlKey])
}

export function ProgressRail({
  scrollHost,
}: {
  readonly scrollHost: RefObject<HTMLElement | null>
}) {
  const [progress, setProgress] = useState(0)
  const frame = useRef(0)

  useEffect(() => {
    const host = scrollHost.current
    if (!host) return

    const measure = () => {
      const scrollable = host.scrollHeight - host.clientHeight
      // A document shorter than the viewport is fully read by definition.
      setProgress(scrollable <= 0 ? 1 : Math.min(1, host.scrollTop / scrollable))
    }

    // Scroll fires far more often than a frame can paint, so the read of
    // layout properties is coalesced into one per frame. Reading scrollTop
    // synchronously on every event is what makes naive scroll handlers janky.
    const onScroll = () => {
      if (frame.current !== 0) return
      frame.current = requestAnimationFrame(() => {
        frame.current = 0
        measure()
      })
    }

    measure()
    host.addEventListener('scroll', onScroll, { passive: true })

    const observer = new ResizeObserver(measure)
    observer.observe(host)

    return () => {
      host.removeEventListener('scroll', onScroll)
      observer.disconnect()
      if (frame.current !== 0) cancelAnimationFrame(frame.current)
    }
  }, [scrollHost])

  return (
    <div className="rail" aria-hidden="true">
      <div className="rail-base" />
      <div className="rail-fill" style={{ transform: `scaleY(${progress})` }} />
      <div className="rail-thumb" style={{ top: `${progress * 100}%` }} />
    </div>
  )
}

export const Prose = memo(function Prose({
  html,
  rootRef,
}: {
  readonly html: string
  readonly rootRef: Ref<HTMLDivElement>
}) {
  return (
    <div
      ref={rootRef}
      className="prose"
      // Sanitised upstream at the pipeline's trust boundary.
      dangerouslySetInnerHTML={{ __html: html }}
    />
  )
})

export function RepairNotice({ repairs }: { readonly repairs: readonly RepairNote[] }) {
  const [open, setOpen] = useState(false)
  const panelId = useId()

  const byRule = new Map<RepairRule, RepairNote[]>()
  for (const note of repairs) {
    const list = byRule.get(note.rule) ?? []
    list.push(note)
    byRule.set(note.rule, list)
  }

  return (
    <aside className="repairs">
      <button
        type="button"
        className="repairs-toggle"
        aria-expanded={open}
        aria-controls={panelId}
        onClick={() => setOpen((v) => !v)}
      >
        <span className="repairs-count">{repairs.length}</span>
        <span>
          {repairs.length === 1 ? 'formatting fix applied' : 'formatting fixes applied'}
        </span>
        <span className="repairs-chevron" aria-hidden="true">
          {open ? '−' : '+'}
        </span>
      </button>

      <div id={panelId} className="repairs-panel" hidden={!open}>
        <p className="repairs-lede">
          The source file was not changed. These adjustments were made only for
          this rendering.
        </p>

        {[...byRule].map(([rule, notes]) => (
          <section key={rule} className="repairs-group">
            <h2 className="repairs-group-title">
              {RULE_LABELS[rule]}
              <span className="repairs-group-count">{notes.length}</span>
            </h2>
            <ul className="repairs-list">
              {notes.slice(0, 8).map((note, i) => (
                <li key={`${rule}-${i}`}>
                  <span className="repairs-line">
                    {note.line === null ? '—' : `line ${note.line}`}
                  </span>
                  <span className="repairs-change">
                    <code>{note.before}</code>
                    <span aria-hidden="true"> → </span>
                    <code>{note.after}</code>
                  </span>
                  <span className="repairs-detail">{note.detail}</span>
                </li>
              ))}
              {notes.length > 8 && (
                <li className="repairs-more">and {notes.length - 8} more</li>
              )}
            </ul>
          </section>
        ))}
      </div>
    </aside>
  )
}

export function Shell() {
  const set = useReader((s) => s.set)
  const activeDocId = useReader((s) => s.activeDocId)
  const openDoc = useReader((s) => s.openDoc)
  const reset = useReader((s) => s.reset)

  const [lightbox, setLightbox] = useState<{ src: string; alt: string } | null>(null)
  const [navOpen, setNavOpen] = useState(false)
  const stage = useRef<HTMLDivElement>(null)

  const docs = set?.docs ?? []
  const index = Math.max(0, docs.findIndex((d) => d.id === activeDocId))
  const activeDoc = docs[index]
  const state = useRenderedDoc(set, activeDoc)

  /** Open a document, optionally scrolling to a heading within it. */
  const navigate = useCallback(
    (docId: string, hash: string | null) => {
      openDoc(docId)
      setNavOpen(false)
      // The target document has to render before its heading exists.
      requestAnimationFrame(() => {
        if (hash === null) {
          stage.current?.scrollTo({ top: 0, behavior: 'instant' })
          return
        }
        document.getElementById(hash)?.scrollIntoView({ block: 'start' })
      })
    },
    [openDoc],
  )

  const step = useCallback(
    (delta: number) => {
      const next = docs[index + delta]
      if (next) navigate(next.id, null)
    },
    [docs, index, navigate],
  )

  // Keyboard navigation. Arrows move between documents; the reader should
  // never need the mouse to get through a set.
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.metaKey || event.ctrlKey || event.altKey) return
      const target = event.target as HTMLElement | null
      // Never hijack keys inside a control.
      if (target && /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName)) return

      switch (event.key) {
        case 'ArrowRight':
        case 'j':
          event.preventDefault()
          step(1)
          break
        case 'ArrowLeft':
        case 'k':
          event.preventDefault()
          step(-1)
          break
        case 'Home':
          if (docs[0]) {
            event.preventDefault()
            navigate(docs[0].id, null)
          }
          break
        case 'End': {
          const last = docs[docs.length - 1]
          if (last) {
            event.preventDefault()
            navigate(last.id, null)
          }
          break
        }
        case 'Escape':
          setNavOpen(false)
          break
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [step, navigate, docs])

  // Scroll to the top of the sheet whenever the document changes, or the
  // reader lands mid-way down a document they have not read yet.
  useEffect(() => {
    stage.current?.scrollTo({ top: 0, behavior: 'instant' })
  }, [activeDocId])

  if (!set || !activeDoc) return null

  const headings = state.kind === 'ready' ? state.result.headings : []

  return (
    <div className={`shell reader${navOpen ? ' nav-open' : ''}`}>
      <a href="#reader-main" className="skip-link">
        Skip to the document
      </a>

      <header className="reader-bar">
        <button
          type="button"
          className="reader-nav-toggle"
          aria-expanded={navOpen}
          aria-controls="reader-index"
          onClick={() => setNavOpen((v) => !v)}
        >
          <span aria-hidden="true">☰</span> Contents
        </button>

        <span className="reader-mark">{set.rootName}</span>
        <span className="reader-rule" aria-hidden="true" />

        <span className="reader-position">
          {index + 1} / {docs.length}
        </span>

        <div className="reader-steps">
          <button
            type="button"
            onClick={() => step(-1)}
            disabled={index === 0}
            aria-label="Previous document"
          >
            ←
          </button>
          <button
            type="button"
            onClick={() => step(1)}
            disabled={index === docs.length - 1}
            aria-label="Next document"
          >
            →
          </button>
        </div>

        <ExportBar set={set} />

        <button type="button" className="reader-close" onClick={reset}>
          Close
        </button>
      </header>

      <div className="reader-body">
        <aside className="reader-index" id="reader-index">
          <IndexSidebar
            set={set}
            activeDoc={activeDoc}
            headings={headings}
            onOpenDoc={(id) => navigate(id, null)}
          />
        </aside>

        {/* Dismisses the index when it is an overlay on narrow screens. */}
        <button
          type="button"
          className="reader-scrim"
          tabIndex={-1}
          aria-hidden="true"
          onClick={() => setNavOpen(false)}
        />

        <main className="reader-stage" id="reader-main" ref={stage} tabIndex={-1}>
          <ProgressRail scrollHost={stage} />

          <div className="sheet reader-sheet">
            {state.kind === 'pending' && (
              <p className="reader-status" role="status">
                Typesetting {activeDoc.title}…
              </p>
            )}

            {state.kind === 'failed' && (
              <p className="reader-status is-error" role="alert">
                {state.message}
              </p>
            )}

            {state.kind === 'ready' && (
              <DocumentView
                doc={activeDoc}
                result={state.result}
                index={index}
                total={docs.length}
                onNavigate={navigate}
                onImageOpen={(src, alt) => setLightbox({ src, alt })}
              />
            )}
          </div>
        </main>
      </div>

      {lightbox && (
        <Lightbox src={lightbox.src} alt={lightbox.alt} onClose={() => setLightbox(null)} />
      )}
    </div>
  )
}

function mapFor<T>(store: WeakMap<DocumentSet, Map<string, T>>, set: DocumentSet) {
  let map = store.get(set)
  if (!map) {
    map = new Map<string, T>()
    store.set(set, map)
  }
  return map
}

export function getCached(set: DocumentSet, docId: string): RenderResult | undefined {
  return cache.get(set)?.get(docId)
}

export function render(set: DocumentSet, doc: MarkdownDoc): Promise<RenderResult> {
  const done = mapFor(cache, set)
  const existing = done.get(doc.id)
  if (existing) return Promise.resolve(existing)

  const pending = mapFor(inflight, set)
  const running = pending.get(doc.id)
  if (running) return running

  const resolveLink = makeLinkResolver(set)
  const promise = renderDocument(doc, { assets: set.assets, resolveLink })
    .then((result) => {
      done.set(doc.id, result)
      pending.delete(doc.id)
      return result
    })
    .catch((err: unknown) => {
      pending.delete(doc.id)
      throw err
    })

  pending.set(doc.id, promise)
  return promise
}

export type RenderState =
  | { readonly kind: 'pending' }
  | { readonly kind: 'ready'; readonly result: RenderResult }
  | { readonly kind: 'failed'; readonly message: string }

export function useRenderedDoc(
  set: DocumentSet | null,
  doc: MarkdownDoc | undefined,
): RenderState {
  // The state carries the id it belongs to. Without that, navigating paints
  // the new document's title beside the *previous* document's body for one
  // frame - React re-renders as soon as the id prop changes, but state only
  // catches up in the effect below. Deriving the mismatch during render
  // closes the gap instead of letting the reader see a mismatched page.
  const [state, setState] = useState<{ docId: string; state: RenderState }>(() => ({
    docId: doc?.id ?? '',
    state: set && doc ? cachedOrPending(set, doc) : { kind: 'pending' },
  }))

  useEffect(() => {
    if (!set || !doc) return

    const cached = getCached(set, doc.id)
    if (cached) {
      setState({ docId: doc.id, state: { kind: 'ready', result: cached } })
      return
    }

    let live = true
    setState({ docId: doc.id, state: { kind: 'pending' } })

    render(set, doc)
      .then((result) => {
        if (live) setState({ docId: doc.id, state: { kind: 'ready', result } })
      })
      .catch((err: unknown) => {
        if (live) {
          setState({
            docId: doc.id,
            state: {
              kind: 'failed',
              message: err instanceof Error ? err.message : 'Could not typeset this document.',
            },
          })
        }
      })

    return () => {
      live = false
    }
  }, [set, doc])

  // Warm the neighbours once the current document is on screen.
  useEffect(() => {
    if (!set || !doc || state.state.kind !== 'ready') return

    const index = set.docs.findIndex((d) => d.id === doc.id)
    const neighbours = [set.docs[index + 1], set.docs[index - 1]].filter(
      (d): d is MarkdownDoc => d !== undefined && d.error === null,
    )

    const idle = requestIdleCallbackShim(() => {
      for (const next of neighbours) void render(set, next).catch(() => undefined)
    })
    return () => cancelIdleCallbackShim(idle)
  }, [set, doc, state.state.kind])

  // A result belonging to a different document is not this document's result.
  // Fall back to the cache for the current id, and to 'pending' otherwise, so
  // the reader never sees one document's body under another's title.
  if (doc && state.docId !== doc.id) {
    const cached = set ? getCached(set, doc.id) : undefined
    return cached ? { kind: 'ready', result: cached } : { kind: 'pending' }
  }

  return state.state
}

function cachedOrPending(set: DocumentSet, doc: MarkdownDoc): RenderState {
  const cached = getCached(set, doc.id)
  return cached ? { kind: 'ready', result: cached } : { kind: 'pending' }
}

function requestIdleCallbackShim(fn: () => void): IdleHandle {
  const w = window as Window & {
    requestIdleCallback?: (cb: () => void, opts?: { timeout: number }) => number
  }
  if (typeof w.requestIdleCallback === 'function') {
    return { kind: 'idle', id: w.requestIdleCallback(fn, { timeout: 2000 }) }
  }
  return { kind: 'timeout', id: window.setTimeout(fn, 300) }
}

function cancelIdleCallbackShim(handle: IdleHandle): void {
  const w = window as Window & { cancelIdleCallback?: (id: number) => void }
  if (handle.kind === 'idle' && typeof w.cancelIdleCallback === 'function') {
    w.cancelIdleCallback(handle.id)
  } else if (handle.kind === 'timeout') {
    window.clearTimeout(handle.id)
  }
}

export type Phase =
  | { readonly kind: 'idle' }
  | { readonly kind: 'reading'; readonly count: number }
  | { readonly kind: 'building' }
  | { readonly kind: 'ready' }
  | { readonly kind: 'error'; readonly message: string; readonly code: string }

interface ReaderState {
  readonly phase: Phase
  readonly set: DocumentSet | null
  /** id of the document currently open. */
  readonly activeDocId: string | null

  ingestDataTransfer(dt: DataTransfer): Promise<void>
  ingestFileList(files: FileList): Promise<void>
  openDoc(docId: string): void
  reset(): void
}

export const useReader = create<ReaderState>((set, get) => {
  /** Object URLs are owned by the set; discarding one without revoking them
   *  leaks every image for the lifetime of the page. */
  const disposeCurrent = () => {
    const current = get().set
    if (current) revokeAssets(current.assets)
  }

  const ingest = async (
    collect: () => Promise<{ path: string; file: File }[]>,
  ): Promise<void> => {
    try {
      set({ phase: { kind: 'reading', count: 0 } })
      const walked = await collect()

      set({ phase: { kind: 'building' } })
      const { rootName, files } = stripCommonRoot(walked)
      const built = await buildDocumentSet(files, { rootName })

      disposeCurrent()
      set({
        set: built,
        activeDocId: built.docs[0]?.id ?? null,
        phase: { kind: 'ready' },
      })
    } catch (err) {
      set({
        phase: {
          kind: 'error',
          message:
            err instanceof IngestError || err instanceof Error
              ? err.message
              : 'Something went wrong reading those files.',
          code: err instanceof IngestError ? err.code : 'read-failed',
        },
      })
    }
  }

  return {
    phase: { kind: 'idle' },
    set: null,
    activeDocId: null,

    ingestDataTransfer: (dt) =>
      ingest(() =>
        walkDataTransfer(dt, {
          maxFiles: LIMITS.maxFiles,
          onProgress: (count) => set({ phase: { kind: 'reading', count } }),
        }),
      ),

    ingestFileList: (files) =>
      ingest(async () =>
        walkFileList(files, {
          maxFiles: LIMITS.maxFiles,
          onProgress: (count) => set({ phase: { kind: 'reading', count } }),
        }),
      ),

    openDoc: (docId) => set({ activeDocId: docId }),

    reset: () => {
      disposeCurrent()
      set({ phase: { kind: 'idle' }, set: null, activeDocId: null })
    },
  }
})

export interface AssetRef {
  /** Normalised POSIX relative path, lowercased — the lookup key. */
  readonly path: string
  /** The path exactly as it appeared in the drop, for display and diagnostics. */
  readonly originalPath: string
  /** Object URL, valid for the lifetime of the session. */
  readonly url: string
  readonly mime: string
  readonly bytes: number
}

export interface Heading {
  /** Slug, unique within its document. */
  readonly id: string
  /** 1..6, after the repair pass has normalised the hierarchy. */
  readonly depth: number
  readonly text: string
  readonly children: Heading[]
}

export interface MarkdownDoc {
  /** Stable hash of the relative path. */
  readonly id: string
  /** Normalised POSIX relative path from the drop root. */
  readonly path: string
  readonly dir: string
  readonly filename: string
  /** frontmatter.title, else the first H1, else a prettified filename. */
  readonly title: string
  readonly frontmatter: Readonly<Record<string, unknown>>
  readonly raw: string
  /** Explicit frontmatter `order`, when present. */
  readonly order: number | null
  /** Composite key computed by ordering.ts; sorting is a plain string compare. */
  readonly sortKey: string
  /** Per-file failure. A failed document never fails the whole set. */
  readonly error: string | null
}

export interface SkippedFile {
  readonly path: string
  readonly reason: string
}

export interface DocumentSet {
  readonly id: string
  /** The dropped folder's name, or 'Documents' for loose files. */
  readonly rootName: string
  /** In resolved reading order. */
  readonly docs: readonly MarkdownDoc[]
  readonly assets: ReadonlyMap<string, AssetRef>
  readonly skipped: readonly SkippedFile[]
  readonly totalBytes: number
  readonly createdAt: number
}

export interface MermaidBlock {
  /** Content-hashed, so a re-render of unchanged source reuses the id and a
   *  changed diagram never collides with the previous one's cached defs. */
  readonly id: string
  readonly code: string
}

export interface RenderResult {
  readonly docId: string
  /** Sanitised, then KaTeX- and Shiki-processed. Safe to inject. */
  readonly html: string
  readonly headings: readonly Heading[]
  readonly repairs: readonly RepairNote[]
  readonly mermaidBlocks: readonly MermaidBlock[]
  readonly wordCount: number
  readonly readingMinutes: number
}

export const IMAGE_EXTENSIONS = [
  '.png', '.jpg', '.jpeg', '.gif', '.webp', '.avif', '.svg', '.bmp', '.ico',
] as const

export class IngestError extends Error {
  constructor(
    message: string,
    readonly code:
      | 'too-large'
      | 'too-many-files'
      | 'no-markdown'
      | 'read-failed',
  ) {
    super(message)
    this.name = 'IngestError'
  }
}

const app = Fastify({
  // Explicit, not the 1MiB default: an export carries every image inlined as
  // a data URI. Unbounded is not an option - a print request is the one place
  // a caller controls how much memory we allocate.
  bodyLimit: PDF_BODY_LIMIT,
  logger: { level: process.env.LOG_LEVEL ?? 'info' },
  trustProxy: false,
})

setHeaders(res, path) {
  if (path.endsWith('index.html')) {
    res.setHeader('cache-control', 'no-cache')
  } else if (/\.[0-9a-f]{8,}\./i.test(path)) {
    res.setHeader('cache-control', 'public, max-age=31536000, immutable')
  }
},

interface PdfBody {
  html?: unknown
  title?: unknown
  format?: unknown
  landscape?: unknown
}

const asciiFilename = (value: string): string => {
  const cleaned = value.replace(/[^\w.-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80)
  return cleaned === '' ? 'documents' : cleaned
}

const close = async (signal: string) => {
  app.log.info({ signal }, 'shutting down')
  await app.close()
  await closeBrowser()
  process.exit(0)
}

async function launch(): Promise<Browser> {
  return chromium.launch({
    args: [
      // Without this Chromium uses /dev/shm, which is small in a container.
      '--disable-dev-shm-usage',
      // No extensions, no first-run UI, no background networking.
      '--no-first-run',
      '--no-default-browser-check',
      '--disable-extensions',
      '--disable-background-networking',
      '--disable-sync',
      '--disable-default-apps',
    ],
  })
}

export function getBrowser(): Promise<Browser> {
  browserPromise ??= launch().then((browser) => {
    // A crashed browser must not be handed out again.
    browser.on('disconnected', () => {
      browserPromise = null
    })
    return browser
  })
  return browserPromise
}

export async function closeBrowser(): Promise<void> {
  const pending = browserPromise
  browserPromise = null
  if (pending) {
    const browser = await pending.catch(() => null)
    await browser?.close().catch(() => undefined)
  }
}

export async function browserHealthy(): Promise<boolean> {
  if (browserPromise === null) return false
  try {
    const browser = await browserPromise
    return browser.isConnected()
  } catch {
    return false
  }
}

export const queueDepth = (): { active: number; pending: number } => ({
  active: limit.activeCount,
  pending: limit.pendingCount,
})

export class BusyError extends Error {
  constructor() {
    super('The print service is busy.')
    this.name = 'BusyError'
  }
}

export class RenderTimeoutError extends Error {
  constructor() {
    super('Rendering took too long.')
    this.name = 'RenderTimeoutError'
  }
}

export interface PdfRequest {
  readonly html: string
  readonly format?: 'A4' | 'Letter'
  readonly landscape?: boolean
  readonly title?: string
}

async function harden(context: BrowserContext): Promise<void> {
  // Registered on the context, not the page, so it covers every frame.
  await context.route('**/*', (route) => {
    const url = route.request().url()
    if (ALLOWED_SCHEMES.test(url)) {
      void route.continue()
      return
    }
    // Everything else: http(s) to any host, file://, ws://. A legitimate
    // export has no remote references, so this only ever blocks an attack.
    void route.abort('blockedbyclient')
  })
}

export async function renderPdf(request: PdfRequest): Promise<Buffer> {
  // Reject rather than queue without bound.
  if (limit.pendingCount > limit.concurrency * 4) throw new BusyError()

  return limit(async () => {
    const browser = await getBrowser()

    const context = await browser.newContext({
      // The single highest-value control. This endpoint prints HTML that has
      // already been rendered, so script execution has no legitimate purpose
      // and its absence removes an entire class of vector.
      javaScriptEnabled: false,
      // storageState is deliberately omitted rather than set to undefined: a
      // fresh context starts with no cookies or storage anyway, and that is
      // the isolation we want between untrusted documents.
      bypassCSP: false,
      // Deterministic output regardless of the host's locale or timezone.
      locale: 'en-GB',
      timezoneId: 'UTC',
      colorScheme: 'light',
      reducedMotion: 'reduce',
      serviceWorkers: 'block',
    })

    try {
      await harden(context)
      context.setDefaultTimeout(PAGE_DEFAULT_TIMEOUT_MS)
      const page = await context.newPage()

      const work = (async () => {
        await page.setContent(request.html, {
          // Deliberately not 'networkidle': with every request aborted, the
          // network never becomes idle in the way Playwright waits for, and
          // the call would sit until it timed out on every single render.
          waitUntil: 'load',
          timeout: SETCONTENT_TIMEOUT_MS,
        })

        // Fonts are inlined as data URIs, but layout still needs them ready
        // or the first page can be typeset with fallback metrics.
        await page
          .evaluate(() => document.fonts.ready.then(() => undefined))
          .catch(() => undefined)

        await page.emulateMedia({ media: 'print' })

        return page.pdf({
          format: request.format ?? 'A4',
          landscape: request.landscape ?? false,
          printBackground: true,
          preferCSSPageSize: true,
          displayHeaderFooter: true,
          headerTemplate: headerTemplate(request.title ?? ''),
          footerTemplate: FOOTER_TEMPLATE,
          margin: { top: '22mm', right: '18mm', bottom: '20mm', left: '22mm' },
        })
      })()

      return await withDeadline(work, RENDER_DEADLINE_MS)
    } finally {
      // Always, even on timeout: a leaked context is a leaked browser process.
      await context.close().catch(() => undefined)
    }
  })
}

function withDeadline<T>(promise: Promise<T>, ms: number): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => reject(new RenderTimeoutError()), ms)
    promise.then(
      (value) => {
        clearTimeout(timer)
        resolve(value)
      },
      (err: unknown) => {
        clearTimeout(timer)
        reject(err instanceof Error ? err : new Error(String(err)))
      },
    )
  })
}
